    write_synthetic_named_object_asset(memo_table_path, memo_path, {
        {
            .objname = "cmdSave",
            .name = "saveButton",
            .unique_id = {},
            .properties = "Caption = \"Save\"\r\nLeft = 10\r\n"
        }
    });
